BEGIN TRANSACTION;
CREATE TABLE item_references(item_id TEXT REFERENCES items(item_id),reference_id TEXT REFERENCES observations(id),PRIMARY KEY(item_id,reference_id));
CREATE TABLE items(item_id TEXT PRIMARY KEY,section_id TEXT,title TEXT,research_state TEXT,accepted_market_rate TEXT,exact_scope_verified INTEGER CHECK(exact_scope_verified=0),record_json TEXT);
CREATE TABLE observations(id TEXT PRIMARY KEY,source_id TEXT REFERENCES sources(id),low TEXT,high TEXT,unit TEXT,basis TEXT,evidence_json TEXT);
CREATE TABLE sources(id TEXT PRIMARY KEY, publisher TEXT, url TEXT, evidence_json TEXT);
COMMIT;
